def schmidt_terms(state, qargs_B):
    from qiskit.quantum_info import Statevector, schmidt_decomposition
    psi = Statevector([complex(r, i) for r, i in state])
    return [{'weight': float(weight),
             'a': [[float(z.real), float(z.imag)] for z in a.data],
             'b': [[float(z.real), float(z.imag)] for z in b.data]}
            for weight, a, b in schmidt_decomposition(psi, qargs_B)
            if weight > 1e-12]

